import pandas as pd
import numpy as np

# Load data
trip_data = pd.read_csv('chunks_csv/cyclehire_w003.csv')
adjacency_data = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Compute Self-Containment Ratio for each borough
self_containment_ratios = {}
for borough in trip_data['StartBorough'].unique():
    departures = (trip_data['StartBorough'] == borough).sum()
    self_contained_trips = (trip_data['StartBorough'] == borough) & (trip_data['EndBorough'] == borough).sum()
    if departures > 0:
        self_containment_ratios[borough] = self_contained_trips / departures
    else:
        self_containment_ratios[borough] = 0

# Identify HOT SPOTS
hot_spots = []
for borough in self_containment_ratios:
    if self_containment_ratios[borough] > 0.8:
        neighbors = adjacency_data[adjacency_data['borough'] == borough]['neighbor'].unique()
        avg_neighbor_ratio = np.mean([self_containment_ratios[n] for n in neighbors if n in self_containment_ratios])
        if avg_neighbor_ratio > 0.7:
            hot_spots.append((borough, self_containment_ratios[borough]))

# Identify COLD SPOTS
cold_spots = []
for borough in self_containment_ratios:
    if self_containment_ratios[borough] < 0.2:
        neighbors = adjacency_data[adjacency_data['borough'] == borough]['neighbor'].unique()
        avg_neighbor_ratio = np.mean([self_containment_ratios[n] for n in neighbors if n in self_containment_ratios])
        if avg_neighbor_ratio < 0.3:
            cold_spots.append((borough, self_containment_ratios[borough]))

# Statistical significance testing
np.random.seed(0)
for spot in hot_spots + cold_spots:
    borough, ratio = spot
    data_points_used = len(trip_data[trip_data['StartBorough'] == borough])
    test_statistic = ratio
    null_distributions = []
    for _ in range(500):
        shuffled_data = trip_data.copy()
        shuffled_data['StartBorough'] = np.random.permutation(shuffled_data['StartBorough'])
        shuffled_ratio = self_containment_ratios[borough]
        null_distributions.append(shuffled_ratio)
    null_distribution = np.array(null_distributions)
    p_value = np.mean(null_distribution >= ratio)
    if p_value < 0.05:
        print(f'{borough} (HH, permutation test with 500 shuffles)')
    else:
        print(f'{borough} (LL, permutation test with 500 shuffles)')

# Reporting
