import pandas as pd
import numpy as np

# Load data
trip_data = pd.read_csv('chunks_csv/cyclehire_w003.csv')
adjacency_data = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Compute Self-Containment Ratio for each borough
self_containment_ratios = {}
for borough in trip_data['StartBorough'].unique():
    departures = (trip_data[trip_data['StartBorough'] == borough].shape[0])
    self_contained_trips = (trip_data[(trip_data['StartBorough'] == borough) & (trip_data['EndBorough'] == borough)].shape[0])
    if departures > 0:
        self_containment_ratios[borough] = self_contained_trips / departures
    else:
        self_containment_ratios[borough] = 0

# Identify HOT SPOTS
hot_spots = []
for borough in self_containment_ratios:
    if self_containment_ratios[borough] > 0.8:
        neighbors = adjacency_data[adjacency_data['borough'] == borough]['neighbor'].unique()
        avg_neighbor_ratio = np.mean([self_containment_ratios[n] for n in neighbors if n in self_containment_ratios])
        if avg_neighbor_ratio > 0.7:
            hot_spots.append((borough, self_containment_ratios[borough]))

# Identify COLD SPOTS
cold_spots = []
for borough in self_containment_ratios:
    if self_containment_ratios[borough] < 0.2:
        neighbors = adjacency_data[adjacency_data['borough'] == borough]['neighbor'].unique()
        avg_neighbor_ratio = np.mean([self_containment_ratios[n] for n in neighbors if n in self_containment_ratios])
        if avg_neighbor_ratio < 0.3:
            cold_spots.append((borough, self_containment_ratios[borough]))

# Statistical significance testing
data_points_used = len(self_containment_ratios)
test_statistic = np.mean([ratio for _, ratio in hot_spots + cold_spots])
p_value = np.mean([np.random.choice([0, 1], size=500, p=[1 - self_containment_ratios[borough], self_containment_ratios[borough]]) < self_containment_ratios[borough] for borough in self_containment_ratios])

# Reporting
if p_value < 0.05:
    print(f'FINAL ANSWER: {", ".join([f"{borough} (HH, permutation test with 500 shuffles)" if (borough, ratio) in hot_spots else f"{borough} (LL, permutation test with 500 shuffles)" for borough, ratio in self_containment_ratios.items() if (borough, ratio) in hot_spots + cold_spots])}')
else:
    print(f'FINAL ANSWER: none')
